'use client'
import { cn } from '@cascivo/core'
import { forwardRef } from 'react'
import type { HTMLAttributes, KeyboardEvent } from 'react'
import styles from './button-group.module.css'

export interface ButtonGroupProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Axis the buttons flow along: `horizontal` puts them in a row, `vertical` stacks them in
   * a column. The seams between them are collapsed either way.
   *
   * @defaultValue `horizontal`
   * @see the component manifest
   */
  orientation?: 'horizontal' | 'vertical'
  size?: 'sm' | 'md' | 'lg'
  /**
   * When true, uses roving tabindex so arrow keys move focus between buttons.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  roving?: boolean
  /**
   * When true, navigation wraps around from end to start.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  loop?: boolean
}

/** Focusable, non-disabled controls inside the group, in DOM order. */
function focusableItems(group: HTMLElement): HTMLElement[] {
  return Array.from(group.querySelectorAll<HTMLElement>('button, a[href], [tabindex]')).filter(
    (el) => !el.hasAttribute('disabled') && el.getAttribute('aria-disabled') !== 'true',
  )
}

export const ButtonGroup = forwardRef<HTMLDivElement, ButtonGroupProps>(function ButtonGroup(
  {
    orientation = 'horizontal',
    size = 'md',
    roving = false,
    loop = false,
    className,
    onKeyDown,
    children,
    ...props
  },
  ref,
) {
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event)
    if (!roving) return
    const horizontal = orientation === 'horizontal'
    const forward = horizontal ? 'ArrowRight' : 'ArrowDown'
    const back = horizontal ? 'ArrowLeft' : 'ArrowUp'
    if (![forward, back, 'Home', 'End'].includes(event.key)) return

    const items = focusableItems(event.currentTarget)
    if (items.length === 0) return
    const current = items.indexOf(document.activeElement as HTMLElement)
    if (current === -1) return

    let next = current
    if (event.key === forward) next = current + 1
    else if (event.key === back) next = current - 1
    else if (event.key === 'Home') next = 0
    else if (event.key === 'End') next = items.length - 1

    if (next < 0) next = loop ? items.length - 1 : 0
    if (next >= items.length) next = loop ? 0 : items.length - 1

    event.preventDefault()
    items[next]?.focus()
  }

  return (
    <div
      role="group"
      data-orientation={orientation}
      data-size={size}
      className={cn(styles['buttonGroup'], className as string | undefined)}
      ref={ref}
      onKeyDown={handleKeyDown}
      {...props}
    >
      {children}
    </div>
  )
})

@layer cascivo.component {
  .buttonGroup {
    display: inline-flex;
    --_radius: var(--cascivo-button-radius, var(--cascivo-radius-control));

    &[data-orientation='horizontal'] {
      flex-direction: row;
    }

    &[data-orientation='vertical'] {
      flex-direction: column;
    }

    /* Collapse the seams between joined children. The children keep their own
       border-radius on the outer edges only; inner corners are squared off. */
    & > * {
      border-radius: 0;
    }

    /* Horizontal: round the inline (leading/trailing) corners, collapse seams. */
    &[data-orientation='horizontal'] {
      & > :first-child {
        border-start-start-radius: var(--_radius);
        border-end-start-radius: var(--_radius);
      }

      & > :last-child {
        border-start-end-radius: var(--_radius);
        border-end-end-radius: var(--_radius);
      }

      & > :not(:first-child) {
        margin-inline-start: -1px;
      }
    }

    /* Vertical: round the block (top/bottom) corners, collapse seams. */
    &[data-orientation='vertical'] {
      & > :first-child {
        border-start-start-radius: var(--_radius);
        border-start-end-radius: var(--_radius);
      }

      & > :last-child {
        border-end-start-radius: var(--_radius);
        border-end-end-radius: var(--_radius);
      }

      & > :not(:first-child) {
        margin-block-start: -1px;
      }
    }

    /* Keep the focused/hovered child above its neighbors so its full border shows. */
    & > :hover,
    & > :focus-visible,
    & > :focus-within {
      position: relative;
      z-index: 1;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'ButtonGroup',
  description: 'Visually joins a set of related buttons into a single segmented control',
  category: 'inputs',
  // A layout wrapper that joins its children visually; the buttons themselves are the
  // caller's.
  clientJs: 'enhancement',
  states: ['idle'],
  variants: [],
  sizes: ['sm', 'md', 'lg'],
  props: [
    {
      name: 'orientation',
      description:
        'Axis the buttons flow along: `horizontal` puts them in a row, `vertical` stacks them in a column. The seams between them are collapsed either way.',
      type: "'horizontal' | 'vertical'",
      required: false,
      default: 'horizontal',
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md' | 'lg'",
      required: false,
      default: 'md',
    },
    {
      name: 'roving',
      description: 'When true, uses roving tabindex so arrow keys move focus between buttons.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'loop',
      description: 'When true, navigation wraps around from end to start.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'aria-label',
      description: 'Accessible label used when no visible label is present.',
      type: 'string',
      required: false,
    },
    {
      name: 'aria-labelledby',
      description: 'Id of the element that labels this component.',
      type: 'string',
      required: false,
    },
  ],
  tokens: ['--cascivo-button-radius', '--cascivo-radius-control'],
  accessibility: {
    role: 'group',
    wcag: '2.2-AA',
    keyboard: ['ArrowRight', 'ArrowLeft', 'ArrowUp', 'ArrowDown', 'Home', 'End'],
    forcedColors: true,
  },
  examples: [
    {
      title: 'Joined actions',
      code: '<ButtonGroup aria-label="Text alignment"><Button>Left</Button><Button>Center</Button><Button>Right</Button></ButtonGroup>',
    },
    {
      title: 'Vertical with roving focus',
      code: '<ButtonGroup orientation="vertical" roving aria-label="View"><Button>List</Button><Button>Grid</Button></ButtonGroup>',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['action', 'segmented', 'toolbar', 'layout'],
  intent: {
    whenToUse: [
      'Presenting several related, independent actions that read as one control (e.g. an editor toolbar)',
      'Visually grouping buttons that share context without implying mutual exclusivity',
    ],
    whenNotToUse: [
      'The buttons represent a single selected value among options — use ToggleGroup',
      'The actions are unrelated and should read as separate buttons — lay them out with spacing instead',
    ],
    antiPatterns: [
      {
        bad: '<ButtonGroup><Button>Bold</Button><Button>Italic</Button></ButtonGroup>',
        good: '<ButtonGroup aria-label="Formatting"><Button>Bold</Button><Button>Italic</Button></ButtonGroup>',
        why: 'A group with no accessible name is announced as an unlabeled region; supply aria-label or aria-labelledby',
      },
    ],
    related: [
      {
        name: 'ToggleGroup',
        relationship: 'alternative',
        reason: 'Use when the buttons select a value rather than fire independent actions',
      },
      {
        name: 'Button',
        relationship: 'contains',
        reason: 'A button group is a layout container for buttons',
      },
    ],
    a11yRationale:
      'Exposes role="group" so assistive tech treats the buttons as one labeled set; optional roving focus lets arrow keys traverse the buttons as a single tab stop, matching toolbar expectations',
    content: {
      tone: 'Imperative verb-first labels on each child button',
      notes: 'Keep child labels parallel in form and length so the segmented control reads evenly',
    },
    flexibility: [
      {
        area: 'token names',
        level: 'strict',
        note: 'Outer corner radius must resolve to --cascivo-button-radius / --cascivo-radius-control to match standalone buttons',
      },
      {
        area: 'children',
        level: 'flexible',
        note: 'Any focusable controls (Button, IconButton, links) may be grouped',
      },
    ],
  },
}
